{"edits":[{"path":"shared/task-ledger-working-context.ts","content":"export type TaskLedgerEventStatus =
  | "pending"
  | "accepted"
  | "rejected"
  | "completed"
  | "failed"
  | "cancelled"
  | string;

export interface TaskLedgerEvent {
  id?: string;
  eventId?: string;
  taskId?: string;
  type?: string;
  status?: TaskLedgerEventStatus;
  workspaceId?: string;
  batchIdempotencyKey?: string;
  createdAt?: string;
  timestamp?: string;
  payload?: unknown;
  [key: string]: unknown;
}

export interface TaskLedgerWorkingContext {
  workspaceId?: string;
  pending: TaskLedgerEvent[];
  accepted: TaskLedgerEvent[];
  tasks: TaskLedgerEvent[];
  events: TaskLedgerEvent[];
}

export interface TaskLedgerWorkingContextOptions {
  workspaceId?: string;
  events?: readonly TaskLedgerEvent[];
}

const PENDING_STATUSES = new Set(["pending", "queued", "submitted", "proposed"]);
const ACCEPTED_STATUSES = new Set(["accepted", "approved", "running", "in_progress"]);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function eventIdentity(event: TaskLedgerEvent, index: number): string {
  const id = event.id ?? event.eventId;
  return id === undefined || id === null ? String(index) : String(id);
}

function eventStatus(event: TaskLedgerEvent): string {
  if (typeof event.status === "string") return event.status.toLowerCase();
  if (typeof event.state === "string") return event.state.toLowerCase();
  if (isRecord(event.payload) && typeof event.payload.status === "string") {
    return event.payload.status.toLowerCase();
  }
  return "pending";
}

function taskIdentity(event: TaskLedgerEvent, index: number): string {
  const id = event.taskId ?? event.task_id ?? event.id ?? event.eventId;
  return id === undefined || id === null ? `event:${eventIdentity(event, index)}` : String(id);
}

/**
 * Projects the append-only ledger into the working-context view. The ledger remains
 * the only source of truth; this function intentionally creates no persistence.
 */
export function projectTaskLedgerWorkingContext(
  eventsOrOptions: readonly TaskLedgerEvent[] | TaskLedgerWorkingContextOptions,
): TaskLedgerWorkingContext {
  const options = Array.isArray(eventsOrOptions)
    ? { events: eventsOrOptions }
    : eventsOrOptions;
  const source = options.events ?? [];
  const events = source.filter(isRecord).map((event) => ({ ...event }));
  const latestByTask = new Map<string, TaskLedgerEvent>();

  events.forEach((event, index) => {
    latestByTask.set(taskIdentity(event, index), event);
  });

  const tasks = Array.from(latestByTask.values());
  const pending = tasks.filter((event) => PENDING_STATUSES.has(eventStatus(event)));
  const accepted = tasks.filter((event) => ACCEPTED_STATUSES.has(eventStatus(event)));

  return {
    ...(options.workspaceId === undefined ? {} : { workspaceId: options.workspaceId }),
    pending,
    accepted,
    tasks,
    events,
  };
}

export const projectWorkingContext = projectTaskLedgerWorkingContext;

export function findTaskLedgerBatch(
  events: readonly TaskLedgerEvent[],
  batchIdempotencyKey: string,
): TaskLedgerEvent | undefined {
  return events.find((event) => event.batchIdempotencyKey === batchIdempotencyKey);
}

export function hasTaskLedgerBatch(
  events: readonly TaskLedgerEvent[],
  batchIdempotencyKey: string,
): boolean {
  return findTaskLedgerBatch(events, batchIdempotencyKey) !== undefined;
}

export class TaskLedgerWorkingContextProjection {
  readonly workspaceId?: string;

  constructor(options: TaskLedgerWorkingContextOptions = {}) {
    this.workspaceId = options.workspaceId;
  }

  project(events: readonly TaskLedgerEvent[]): TaskLedgerWorkingContext {
    return projectTaskLedgerWorkingContext({
      workspaceId: this.workspaceId,
      events,
    });
  }
}
"},{"path":"electron/services/task-ledger-working-context.ts","content>import { promises as fs } from "node:fs";
import path from "node:path";
import {
  findTaskLedgerBatch,
  hasTaskLedgerBatch,
  projectTaskLedgerWorkingContext,
  projectWorkingContext,
  TaskLedgerWorkingContextProjection,
  type TaskLedgerEvent,
  type TaskLedgerWorkingContext,
  type TaskLedgerWorkingContextOptions,
} from "../../shared/task-ledger-working-context";

export {
  findTaskLedgerBatch,
  hasTaskLedgerBatch,
  projectTaskLedgerWorkingContext,
  projectWorkingContext,
  TaskLedgerWorkingContextProjection,
};
exnexport type { TaskLedgerEvent, TaskLedgerWorkingContext, TaskLedgerWorkingContextOptions };

export const TASK_LEDGER_FILE_NAME = "task-ledger.jsonl";

export interface TaskLedgerWorkingContextStoreOptions {
  workspaceId?: string;
  workspaceRoot?: string;
  workspaceDir?: string;
  ledgerPath?: string;
  ledgerFileName?: string;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function toEvent(value: unknown): TaskLedgerEvent {
  if (!isRecord(value)) {
    throw new TypeError("Task ledger entries must be JSON objects");
  }
  return value as TaskLedgerEvent;
}

function parseLedger(contents: string): TaskLedgerEvent[] {
  const events: TaskLedgerEvent[] = [];
  const lines = contents.split(/\r?\n/);
  for (const line of lines) {
    if (line.trim() === "") continue;
    events.push(toEvent(JSON.parse(line)));
  }
  return events;
}

export class TaskLedgerWorkingContextStore {
  readonly workspaceId?: string;
  readonly ledgerPath: string;
  private readonly workspaceRoot?: string;

  constructor(options: TaskLedgerWorkingContextStoreOptions | string = {}) {
    const resolved = typeof options === "string" ? { workspaceRoot: options } : options;
    this.workspaceId = resolved.workspaceId;
    this.workspaceRoot = resolved.workspaceRoot ?? resolved.workspaceDir;

    if (resolved.ledgerPath) {
      this.ledgerPath = path.resolve(resolved.ledgerPath);
    } else if (this.workspaceRoot) {
      this.ledgerPath = path.join(
        path.resolve(this.workspaceRoot),
        resolved.ledgerFileName ?? TASK_LEDGER_FILE_NAME,
      );
    } else {
      throw new TypeError("A workspace root or ledger path is required");
    }
  }

  async readEvents(): Promise<TaskLedgerEvent[]> {
    let contents: string;
    try {
      contents = await fs.readFile(this.ledgerPath, "utf8");
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
      throw error;
    }
    return parseLedger(contents);
  }

  async read(): Promise<TaskLedgerWorkingContext> {
    const events = await this.readEvents();
    return projectTaskLedgerWorkingContext({
      workspaceId: this.workspaceId,
      events,
    });
  }

  async projection(): Promise<TaskLedgerWorkingContext> {
    return this.read();
  }

  async append(event: TaskLedgerEvent): Promise<TaskLedgerWorkingContext> {
    const batchKey = event.batchIdempotencyKey;
    const existing = await this.readEvents();

    if (batchKey !== undefined && hasTaskLedgerBatch(existing, batchKey)) {
      return this.read();
    }

    const serialized = `${JSON.stringify(event)}\n`;
    await fs.mkdir(path.dirname(this.ledgerPath), { recursive: true });

    // appendFile reports permission and I/O failures to the caller. No fallback
    // store is created because the JSONL ledger is the sole source of truth.
    await fs.appendFile(this.ledgerPath, serialized, { encoding: "utf8", flag: "a" });
    return this.read();
  }

  async appendEvent(event: TaskLedgerEvent): Promise<TaskLedgerWorkingContext> {
    return this.append(event);
  }

  async appendBatch(
    events: readonly TaskLedgerEvent[],
    batchIdempotencyKey?: string,
  ): Promise<TaskLedgerWorkingContext> {
    const batch = events.map((event) =>
      batchIdempotencyKey === undefined
        ? event
        : { ...event, batchIdempotencyKey: event.batchIdempotencyKey ?? batchIdempotencyKey },
    );
    const existing = await this.readEvents();

    if (
      batchIdempotencyKey !== undefined &&
      hasTaskLedgerBatch(existing, batchIdempotencyKey)
    ) {
      return this.read();
    }

    if (batch.length > 0) {
      await fs.mkdir(path.dirname(this.ledgerPath), { recursive: true });
      const serialized = batch.map((event) => `${JSON.stringify(event)}\n`).join("");
      await fs.appendFile(this.ledgerPath, serialized, { encoding: "utf8", flag: "a" });
    }
    return this.read();
  }
}

export interface AppendTaskLedgerWorkingContextOptions extends TaskLedgerWorkingContextStoreOptions {
  event: TaskLedgerEvent;
}

export async function appendTaskLedgerWorkingContext(
  options: AppendTaskLedgerWorkingContextOptions,
): Promise<TaskLedgerWorkingContext> {
  const store = new TaskLedgerWorkingContextStore(options);
  return store.append(options.event);
}

export async function readTaskLedgerWorkingContext(
  options: TaskLedgerWorkingContextStoreOptions,
): Promise<TaskLedgerWorkingContext> {
  const store = new TaskLedgerWorkingContextStore(options);
  return store.read();
}

export async function readTaskLedgerEvents(
  options: TaskLedgerWorkingContextStoreOptions,
): Promise<TaskLedgerEvent[]> {
  const store = new TaskLedgerWorkingContextStore(options);
  return store.readEvents();
}

export function createTaskLedgerWorkingContextStore(
  options: TaskLedgerWorkingContextStoreOptions,
): TaskLedgerWorkingContextStore {
  return new TaskLedgerWorkingContextStore(options);
}
"}]}

