  async append(event: TaskLedgerEvent): Promise<TaskLedgerWorkingContext> {
    const batchKey = event.batchIdempotencyKey;
    const existing = await this.readEvents();

    if (batchKey !== undefined && hasTaskLedgerBatch(existing, batchKey)) {
      return this.read();
    }

    const serialized = `${JSON.stringify(event)}\n`;
    await fs.mkdir(path.dirname(this.ledgerPath), { recursive: true });

    // appendFile reports permission and I/O failures to the caller. No fallback
    // store is created because the JSONL ledger is the sole source of truth.
    await fs.appendFile(this.ledgerPath, serialized, { encoding: "utf8", flag: "a" });
    return this.read();
  }

  async appendEvent(event: TaskLedgerEvent): Promise<TaskLedgerWorkingContext> {
    return this.append(event);
  }

  async appendBatch(
    events: readonly TaskLedgerEvent[],
    batchIdempotencyKey?: string,
  ): Promise<TaskLedgerWorkingContext> {
    const batch = events.map((event) =>
      batchIdempotencyKey === undefined
        ? event
        : { ...event, batchIdempotencyKey: event.batchIdempotencyKey ?? batchIdempotencyKey },
    );
    const existing = await this.readEvents();

    if (
      batchIdempotencyKey !== undefined &&
      hasTaskLedgerBatch(existing, batchIdempotencyKey)
    ) {
      return this.read();
    }

    if (batch.length > 0) {
      await fs.mkdir(path.dirname(this.ledgerPath), { recursive: true });
      const serialized = batch.map((event) => `${JSON.stringify(event)}\n`).join("");
      await fs.appendFile(this.ledgerPath, serialized, { encoding: "utf8", flag: "a" });
    }
    return this.read();
  }
}

export interface AppendTaskLedgerWorkingContextOptions extends TaskLedgerWorkingContextStoreOptions {
  event: TaskLedgerEvent;
}

export async function appendTaskLedgerWorkingContext(
  options: AppendTaskLedgerWorkingContextOptions,
): Promise<TaskLedgerWorkingContext> {
  const store = new TaskLedgerWorkingContextStore(options);
  return store.append(options.event);
}

export async function readTaskLedgerWorkingContext(
  options: TaskLedgerWorkingContextStoreOptions,
): Promise<TaskLedgerWorkingContext> {
  const store = new TaskLedgerWorkingContextStore(options);
  return store.read();
}

export async function readTaskLedgerEvents(
  options: TaskLedgerWorkingContextStoreOptions,
): Promise<TaskLedgerEvent[]> {
  const store = new TaskLedgerWorkingContextStore(options);
  return store.readEvents();
}

export function createTaskLedgerWorkingContextStore(
  options: TaskLedgerWorkingContextStoreOptions,
): TaskLedgerWorkingContextStore {
  return new TaskLedgerWorkingContextStore(options);
}
